// ============================================================================
// NOVA ATELIER — Testimonial Panel (hub-visual-stage child)
// 1. COMPOSITION: a 3.4x1.9 machined panel (rounded corners) floats on a dark
//    ink backdrop plate; an oversized red quote-mark sits top-left (0.5 pad),
//    quote copy below it, then an accent rule + attribution + caption row.
// 2. LIGHT RIG: rig-soft-wrap — key directional (#ffefdd, 2.0), hemisphere
//    fill (#efe8de, 0.5), rim directional (#fff8f0, 0.9) — all node-local.
// 3. MATERIALS: MeshPhysicalNodeMaterial panel with vertical gradient
//    colorNode (#1a1a22 -> #111116), roughness 0.6/metalness 0.2/clearcoat
//    0.1; ink/surface backing plates give layered depth; accent rule emissive.
// 4. MOTION: panel fade-up (opacity 0->1, y +0.2->0, 0.5s power2.out), then
//    quote-mark weighted-settle (scale 1.04->1.0, 0.9s power4.out). No idle.
// 5. FOCAL ELEMENT: the oversized red quotation mark — brightest, boldest,
//    catches the key light's raking edge, everything else graded below it.
// ============================================================================

import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { positionLocal, mix, vec3, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

const BACKGROUND = '#0b0b10';
const SURFACE = '#16161d';
const INK = '#16161d';
const PAPER = '#e8ecf2';
const ACCENT = '#ff2a38';
const GRADIENT_TOP = '#1a1a22';
const GRADIENT_BOTTOM = '#111116';

function hexToVec3(THREE, hex) {
  const c = new THREE.Color(hex);
  return vec3(c.r, c.g, c.b);
}

function createRoundedRectShape(THREE, w, h, r) {
  const shape = new THREE.Shape();
  const hw = w / 2;
  const hh = h / 2;
  shape.moveTo(-hw + r, -hh);
  shape.lineTo(hw - r, -hh);
  shape.quadraticCurveTo(hw, -hh, hw, -hh + r);
  shape.lineTo(hw, hh - r);
  shape.quadraticCurveTo(hw, hh, hw - r, hh);
  shape.lineTo(-hw + r, hh);
  shape.quadraticCurveTo(-hw, hh, -hw, hh - r);
  shape.lineTo(-hw, -hh + r);
  shape.quadraticCurveTo(-hw, -hh, -hw + r, -hh);
  return shape;
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, DirectionalLight, HemisphereLight, Mesh, PlaneGeometry, ExtrudeGeometry, BoxGeometry } = THREE;

  const root = new Group();
  root.name = 'testimonial-panel';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findItem = (role, fallback) => (items.find((i) => i.role === role)?.text ?? fallback);

  const quoteMarkText = findItem('quote-mark', '"');
  const quoteText = findItem('quote', '');
  const attributionText = findItem('attribution', '');
  const captionText = findItem('caption', '');

  const disposables = [];
  const timelines = [];

  // -- STAGE BACKDROP (color.background) ------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const bgTop = hexToVec3(THREE, '#1c1c24');
  const bgBottom = hexToVec3(THREE, BACKGROUND);
  const bgT = positionLocal.y.negate().add(3.0).div(6.0).clamp(0, 1);
  backdropMat.colorNode = mix(bgTop, bgBottom, bgT);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // -- INK BACKING PLATE (color.ink) — layered depth behind the panel -------
  const inkShape = createRoundedRectShape(THREE, 3.52, 2.02, 0.07);
  const inkGeo = new ExtrudeGeometry(inkShape, { depth: 0.02, bevelEnabled: false });
  const inkMat = new MeshPhysicalNodeMaterial({
    colorNode: hexToVec3(THREE, INK),
    roughness: 0.75,
    metalness: 0.15,
  });
  const inkPlate = new Mesh(inkGeo, inkMat);
  inkPlate.position.set(0, 0, -0.12);
  root.add(inkPlate);
  disposables.push(inkGeo, inkMat);

  // -- SURFACE PANEL BODY (color.surface / effects.spec) ---------------------
  const PANEL_W = 3.4;
  const PANEL_H = 1.9;
  const CORNER_R = 0.06;
  const panelShape = createRoundedRectShape(THREE, PANEL_W, PANEL_H, CORNER_R);
  const panelGeo = new ExtrudeGeometry(panelShape, {
    depth: 0.08,
    bevelEnabled: true,
    bevelThickness: 0.01,
    bevelSize: 0.01,
    bevelSegments: 2,
  });
  panelGeo.translate(0, 0, -0.04);

  const gradTop = hexToVec3(THREE, GRADIENT_TOP);
  const gradBottom = hexToVec3(THREE, GRADIENT_BOTTOM);
  const surfaceTint = hexToVec3(THREE, SURFACE);
  const gradT = positionLocal.y.negate().add(PANEL_H / 2).div(PANEL_H).clamp(0, 1);
  const baseGrad = mix(gradTop, gradBottom, gradT);
  const panelColor = mix(baseGrad, surfaceTint, float(0.12));

  const panelMat = new MeshPhysicalNodeMaterial({
    colorNode: panelColor,
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    transparent: true,
    opacity: 1,
  });
  const panelMesh = new Mesh(panelGeo, panelMat);
  panelMesh.position.set(0, 0, 0);
  root.add(panelMesh);
  disposables.push(panelGeo, panelMat);

  // -- HAIRLINE BORDER (effects.spec: 0.006-unit hairline #26262f) ----------
  const borderShape = createRoundedRectShape(THREE, PANEL_W + 0.012, PANEL_H + 0.012, CORNER_R + 0.006);
  const borderGeo = new ExtrudeGeometry(borderShape, { depth: 0.02, bevelEnabled: false });
  const borderMat = new MeshPhysicalNodeMaterial({
    colorNode: hexToVec3(THREE, '#26262f'),
    roughness: 0.55,
    metalness: 0.25,
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.set(0, 0, -0.045);
  root.add(borderMesh);
  disposables.push(borderGeo, borderMat);

  // -- QUOTATION MARK (text.quote-mark.0 / color.accent focal element) ------
  const padding = 0.5;
  const leftX = -PANEL_W / 2 + padding;
  const topY = PANEL_H / 2 - padding;

  // pseudo-extrusion shadow layer (0.04 unit depth illusion)
  const quoteMarkShadow = ctx.fontAtlas.createText(quoteMarkText, {
    fontSize: 62,
    color: '#8f0f18',
    align: 'left',
  });
  quoteMarkShadow.position.set(leftX + 0.01, topY - 0.01, 0.04);
  root.add(quoteMarkShadow);

  const quoteMark = ctx.fontAtlas.createText(quoteMarkText, {
    fontSize: 62,
    color: ACCENT,
    align: 'left',
  });
  quoteMark.position.set(leftX, topY, 0.08);
  root.add(quoteMark);

  // -- QUOTE COPY (text.quote.1) — floats +0.03 above panel plane -----------
  const quoteMesh = ctx.fontAtlas.createText(quoteText, {
    fontSize: 20,
    color: PAPER,
    align: 'left',
    maxWidthPx: 240,
  });
  quoteMesh.position.set(leftX, topY - 0.62 - 0.25, 0.07);
  root.add(quoteMesh);

  // -- ACCENT RULE (effects.spec: 0.2w x 0.02h emissive accent) -------------
  const ruleGeo = new BoxGeometry(0.2, 0.02, 0.01);
  const ruleMat = new MeshPhysicalNodeMaterial({
    colorNode: hexToVec3(THREE, ACCENT),
    emissiveNode: hexToVec3(THREE, ACCENT).mul(1.4),
    roughness: 0.4,
    metalness: 0.1,
  });
  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  const attribRowY = topY - 0.62 - 0.25 - 0.87 - 0.25;
  ruleMesh.position.set(leftX + 0.1, attribRowY, 0.06);
  root.add(ruleMesh);
  disposables.push(ruleGeo, ruleMat);

  // -- ATTRIBUTION (text.attribution.2) --------------------------------------
  const attributionMesh = ctx.fontAtlas.createText(attributionText, {
    fontSize: 13,
    color: PAPER,
    align: 'left',
    letterSpacingPx: 13 * 0.08,
  });
  attributionMesh.position.set(leftX + 0.3, attribRowY, 0.06);
  root.add(attributionMesh);

  // -- CAPTION (text.caption.3) ----------------------------------------------
  const captionMesh = ctx.fontAtlas.createText(captionText, {
    fontSize: 9,
    color: PAPER,
    align: 'left',
    letterSpacingPx: 9 * 0.12,
  });
  captionMesh.position.set(leftX, attribRowY - 0.22, 0.06);
  root.add(captionMesh);

  // -- LIGHT RIG (preset rig-soft-wrap, node-local) --------------------------
  const keyLight = new DirectionalLight('#ffefdd', 2.0);
  keyLight.position.set(1.8, 2.2, 2.8);
  keyLight.target.position.set(0, 0.5, 0);
  root.add(keyLight, keyLight.target);

  const fillLight = new HemisphereLight('#efe8de', BACKGROUND, 0.5);
  root.add(fillLight);

  const rimLight = new DirectionalLight('#fff8f0', 0.9);
  rimLight.position.set(-1, 1.8, -2.4);
  rimLight.target.position.set(0, 0.5, 0);
  root.add(rimLight, rimLight.target);

  // -- MOTION: fade-up panel then weighted-settle quote mark -----------------
  root.position.y += 0;
  const startY = root.position.y + 0.2;
  root.position.y = startY;
  panelMat.opacity = 0;
  quoteMark.scale.setScalar(1.04);
  quoteMarkShadow.scale.setScalar(1.04);

  const tl = gsap.timeline();
  tl.to(root.position, {
    y: startY - 0.2,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  tl.to(panelMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => { panelMat.needsUpdate = true; },
  }, 0);
  tl.to([quoteMark.scale, quoteMarkShadow.scale], {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.5);
  timelines.push(tl);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const tlItem of timelines) {
      tlItem.kill();
    }
    timelines.length = 0;

    root.traverse((obj) => {
      if (obj.geometry && typeof obj.geometry.dispose === 'function') {
        obj.geometry.dispose();
      }
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          if (m && typeof m.dispose === 'function') m.dispose();
        }
      }
    });

    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    disposables.length = 0;

    root.remove(keyLight, keyLight.target, fillLight, rimLight, rimLight.target);
  };

  return root;
}

